const { execSync } = require("child_process");
const fs = require('fs');

execSync("npm install --no-audit --progress=false sfdc-soup@18.4.0 jsforce", {stdio: 'inherit'});

const sfdcSoup = require('/app/node_modules/sfdc-soup');
const jsforce = require('/app/node_modules/jsforce');

const copadoConn = new jsforce.Connection({
    serverUrl : 'https://'+ new URL(process.env.CF_SF_ENDPOINT).hostname,
    sessionId : process.env.CF_SF_SESSIONID
});

const sandboxConn = new jsforce.Connection({
    serverUrl : 'https://'+ new URL(process.env.sourceEndpoint).hostname,
    sessionId : process.env.sourceSessionId
});

const sfdcConnection = {
    url: 'https://'+ new URL(process.env.sourceEndpoint).hostname, 
    token: process.env.sourceSessionId,
    apiVersion: '56.0'
};

async function getMetadataItemsOfType(type, names) {
    console.time("listmetadata");
    let metadataItems = await sandboxConn.metadata.list([{type: type}], '56.0');
    // we need to check if .list() returns an array
    // https://github.com/jsforce/jsforce/issues/871
    if(!Array.isArray(metadataItems)) {
        metadataItems = [metadataItems];
    }
    console.timeEnd("listmetadata");

    const matches = metadataItems.filter( item => names.includes(item.fullName) );
    if(!matches.length) {
        console.log('cannot find item ', names);
        for(const item of metadataItems) {
            console.debug(item.id, item.type, item.fullName);
        }
    }
    return matches;
}

async function getListOfMetadataFromUserStory(userStoryId) {
    let metadataList = [];
    let metadataListMap = {};
    let response;

    response = await copadoConn.query("SELECT ContentDocument.LatestPublishedVersionId FROM ContentDocumentLink WHERE LinkedEntityId = '"+userStoryId+"' AND ContentDocument.Title = 'Copado Commit changes' ORDER BY ContentDocument.ContentModifiedDate DESC LIMIT 1");
    if(response.records.length && response.records[0].ContentDocument.LatestPublishedVersionId) {
        const contentVersionId = response.records[0].ContentDocument.LatestPublishedVersionId;

        const result = await copadoConn.request('/services/data/v56.0/sobjects/ContentVersion/'+contentVersionId+'/VersionData');
        metadataList = JSON.parse(result);

        // generate a map of the metadata items, to avoid duplicates when merging with the US metadata
        metadataListMap = metadataList.reduce((group, item) => {
            const key = `${item.t}.${item.n}`
            group[key] = group[key] ?? [];
            group[key].push(item);
            return group;
          }, {});
    }

    response = await copadoConn.query("SELECT copado__Type__c, copado__Metadata_API_Name__c FROM copado__User_Story_Metadata__c WHERE copado__User_Story__c = '"+userStoryId+"' ORDER BY copado__Type__c, copado__Metadata_API_Name__c");
    for(const item of response.records) {
        const key = `${item.copado__Type__c}.${item.copado__Metadata_API_Name__c}`;
        if( !(key in metadataListMap) ) {
            metadataList.push({t: item.copado__Type__c, n: item.copado__Metadata_API_Name__c})
        }
    }
    return metadataList;
}

async function getUserStoryAndResult(parentId) {
    let resp;
    let resultId;
    let userStoryId;
    resp = await copadoConn.query("SELECT Id FROM copado__Result__c WHERE copado__Test__c = '"+parentId+"' ORDER BY CreatedDate DESC LIMIT 1");
    if(resp.records.length) {
        // parentId is a Test object (used as a Test Tool)
        resultId = resp.records[0].Id;
        resp = await copadoConn.query("SELECT copado__User_Story__c FROM copado__Test__c WHERE Id = '"+parentId+"'");
        if(!resp.records.length || !resp.records[0].copado__User_Story__c) {
            throw new Error('Could not find the User Story (1)');
        }
        userStoryId = resp.records[0].copado__User_Story__c;
    }else{
        // parentId is a UserStoryCommit object (used as a Quality Gate)
        resp = await copadoConn.query("SELECT copado__User_Story__c FROM copado__User_Story_Commit__c WHERE Id = '"+parentId+"'");
        if(!resp.records.length || !resp.records[0].copado__User_Story__c) {
            throw new Error('Could not find the User Story (2)');
        }
        userStoryId = resp.records[0].copado__User_Story__c;

        resp = await copadoConn.query("SELECT copado__Result__c FROM copado__JobStep__c WHERE copado__JobExecution__r.copado__UserStoryCommit__c = '"+parentId+"' ORDER BY CreatedDate DESC LIMIT 1");
        if(!resp.records.length || !resp.records[0].copado__Result__c) {
            throw new Error('Could not find the Result');
        }
        resultId = resp.records[0].copado__Result__c;
    }
    return {userStoryId, resultId}
}

const start = async () => {
    console.log('[param] parentId=', process.env.parentId);

    const {userStoryId, resultId} = await getUserStoryAndResult(process.env.parentId)
    const changes = await getListOfMetadataFromUserStory(userStoryId);

    if(!changes.length) {
        throw new Error('The user story has no metadata items to scan');
    }

    let items = [];
    for(const c of changes) {
        console.log(c);
        items = items.concat(await getMetadataItemsOfType(c.t, [c.n]));
    }

    if(!items.length) {
        throw new Error('Could not find any metadata items to scan');
    }

    let result = {
        "version": "2.1.0",
        "$schema": "http://json.schemastore.org/sarif-2.1.0",
        "runs": [
            {
            "tool": {
                "driver": {
                "name": "happy-soup",
                "rules": []
                }
            },
            "results": [],
            "invocations": [
                {
                "executionSuccessful": true,
                "toolExecutionNotifications": []
                }
            ]
            }
        ]
    };


    for(const item of items) {
        console.debug(item.id, item.type, item.fullName);

        const request = {
            name: item.fullName, 
            type: item.type, 
            id: item.id
        };
        const soupApi = sfdcSoup(sfdcConnection, request);

        console.time("getUsage");
        const ur = await soupApi.getUsage();
        console.timeEnd("getUsage");

        console.log('##### USAGE OF', item.fullName)
        console.log(ur.csv);

        let usagesBuf = [];
        const usageTree = Object.values(ur.usageTree);
        if(usageTree.length) {
            for( const subitems of usageTree ) {
                for(const item of subitems) {
                    const ns = item.namespace? `${item.namespace}__` : '';
                    usagesBuf.push(`referenced at ${ns}${item.name} (${item.type})`);
                }
            }
        }else{
            usagesBuf.push('(no referenced found)');
        }

        result.runs[0].results.push({
            "level": "info",
            "ruleId": `${ur.entryPoint.name} (${ur.entryPoint.type})`,
            "locations": [],
            "message": usagesBuf.join('\n')
        });
    }

    let data = JSON.stringify(result);
    fs.writeFileSync('/tmp/metadata_report_hs.json', data);

    execSync("copado -p 'uploading results to "+resultId+"'", {stdio: 'inherit'});

    execSync("copado -u /tmp/metadata_report_hs.json --parentid "+resultId, {stdio: 'inherit'});
};

// never fail, because we do not want to interrupt the copado action if there is a problem.
start().catch((e) => { console.error('there was a problem executing the scan', e); });

'use strict';

/**
 * Syncs data template field selections for the current environment.
 *
 * Downloads DataTemplatesSyncConfig ContentVersions, merges them, keeps only
 * the not-yet-synced entries for the current environmentId, deduplicates, and
 * POSTs the payload to the CICD gateway /data-templates/sync endpoint.
 *
 * @param environmentId - Environment Id of the org where commit/deploy is running
 * @param dataTemplatesSyncConfigIds - Stringified JSON array of ContentVersion Ids
 */

const child_process = require('child_process');
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const process = require('process');

const { environmentId, dataTemplatesSyncConfigIds, CF_SF_ENDPOINT, locale, isTest } = process.env;

const TEMP_DIRECTORY = getPath('/tmp/sync_data_templates');
const SYNC_CONFIG_FILE_NAME = 'DataTemplatesSyncConfig';
const SYNC_RESULT_FILE_NAME = 'DataTemplatesSyncResult.json';
const COPADO_INFO_PREFIX = 'CopadoFunction INFO';
const VALID_OPERATIONS = new Set(['add', 'delete']);
const SYNC_PAYLOAD_FIELDS = [
	'mainTemplateId',
	'templateId',
	'objectApiName',
	'fieldApiName',
	'fieldType',
	'operation',
	'column',
	'environmentId'
];

const CUSTOM_ERROR = {
	COMMAND_EXECUTION_ERROR: 'CommandExecutionError',
	VALIDATION_ERROR: 'ValidationError',
	SYNC_ERROR: 'SyncError'
};

// EXECUTION

async function execute() {
	try {
		this.logger('Starting Sync Data Templates');

		const contentVersionIds = this.parseContentVersionIds(dataTemplatesSyncConfigIds);
		this.logger(`Downloading ${contentVersionIds.length} DataTemplatesSyncConfig file(s)`);
		const syncConfigs = await this.downloadAndReadSyncConfigs(contentVersionIds);

		const payload = this.buildSyncPayload(syncConfigs, environmentId);
		this.logger(`Prepared ${payload.length} sync operation(s) for environment ${environmentId}`);

		if (!payload.length) {
			this.logger('No matching sync operations for this environment. Skipping gateway call.');
			return;
		}

		const syncResponse = await this.callDataTemplatesSync(payload);
		await this.handleSyncResponse(syncResponse);

		this.logger('Sync Data Templates completed');
	} catch (err) {
		this.logger(`Error: ${err.message}`);
		process.exit(1);
	}
}

// SCRIPT FUNCTIONS

function parseContentVersionIds(rawIds) {
	let contentVersionIds;
	try {
		contentVersionIds = JSON.parse(rawIds);
	} catch (error) {
		throw new ValidationError(`dataTemplatesSyncConfigIds must be a JSON array: ${error.message}`);
	}

	if (!Array.isArray(contentVersionIds)) {
		throw new ValidationError('dataTemplatesSyncConfigIds must be a JSON array');
	}

	const normalizedIds = contentVersionIds
		.map(id => (typeof id === 'string' ? id.trim() : id))
		.filter(id => typeof id === 'string' && id.length > 0);

	if (!normalizedIds.length) {
		throw new ValidationError('dataTemplatesSyncConfigIds must contain at least one ContentVersion Id');
	}

	return [...new Set(normalizedIds)];
}

async function downloadAndReadSyncConfigs(contentVersionIds) {
	const mergedConfigs = [];

	for (const contentVersionId of contentVersionIds) {
		const downloadDir = path.join(TEMP_DIRECTORY, contentVersionId);
		await this.downloadContentVersion(contentVersionId, downloadDir);
		const fileContent = this.readDownloadedSyncConfig(downloadDir, contentVersionId);
		if (!Array.isArray(fileContent)) {
			throw new ValidationError(
				`ContentVersion ${contentVersionId} must contain a JSON array of sync config entries`
			);
		}
		mergedConfigs.push(...fileContent);
	}

	return mergedConfigs;
}

async function downloadContentVersion(contentVersionId, downloadDir) {
	fs.mkdirSync(downloadDir, { recursive: true });
	await this.executeCommand(
		`copado --downloadfiles "${contentVersionId}" --downloaddir "${downloadDir}"`
	);
}

function readDownloadedSyncConfig(downloadDir, contentVersionId) {
	const preferredPaths = [
		path.join(downloadDir, SYNC_CONFIG_FILE_NAME),
		path.join(downloadDir, `${SYNC_CONFIG_FILE_NAME}.json`)
	];

	for (const preferredPath of preferredPaths) {
		if (fs.existsSync(preferredPath) && fs.statSync(preferredPath).isFile()) {
			return this.readJsonFile(preferredPath);
		}
	}

	const files = fs
		.readdirSync(downloadDir)
		.map(fileName => path.join(downloadDir, fileName))
		.filter(filePath => fs.statSync(filePath).isFile());

	if (!files.length) {
		throw new ValidationError(`No downloaded sync config file found for ContentVersion ${contentVersionId}`);
	}

	if (files.length === 1) {
		return this.readJsonFile(files[0]);
	}

	const jsonFiles = files.filter(filePath => path.extname(filePath).toLowerCase() === '.json');
	if (jsonFiles.length === 1) {
		return this.readJsonFile(jsonFiles[0]);
	}

	throw new ValidationError(
		`Expected one sync config file for ContentVersion ${contentVersionId}, found ${files.length}`
	);
}

function buildSyncPayload(syncConfigs, currentEnvironmentId) {
	const filtered = this.filterSyncConfigsForEnvironment(syncConfigs, currentEnvironmentId);
	const deduplicated = this.deduplicateSyncConfigs(filtered);
	return deduplicated.map(entry => this.toSyncRequestEntry(entry));
}

function filterSyncConfigsForEnvironment(syncConfigs, currentEnvironmentId) {
	return syncConfigs.filter(entry => {
		if (!entry || typeof entry !== 'object') {
			return false;
		}
		if (entry.environmentId !== currentEnvironmentId) {
			return false;
		}
		if (entry.synced === true) {
			return false;
		}
		if (!VALID_OPERATIONS.has(entry.operation)) {
			return false;
		}
		if (!entry.mainTemplateId || !entry.fieldApiName) {
			return false;
		}
		return true;
	});
}

function deduplicateSyncConfigs(syncConfigs) {
	const seen = new Set();
	const deduplicated = [];

	for (const entry of syncConfigs) {
		const key = this.getSyncConfigDedupeKey(entry);
		if (seen.has(key)) {
			continue;
		}
		seen.add(key);
		deduplicated.push(entry);
	}

	return deduplicated;
}

function getSyncConfigDedupeKey(entry) {
	return [
		entry.mainTemplateId,
		entry.templateId,
		entry.objectApiName,
		entry.fieldApiName,
		entry.fieldType,
		entry.operation
	].join('|');
}

function toSyncRequestEntry(entry) {
	const requestEntry = {};
	for (const field of SYNC_PAYLOAD_FIELDS) {
		if (entry[field] !== undefined && entry[field] !== null) {
			requestEntry[field] = entry[field];
		}
	}
	return requestEntry;
}

async function callDataTemplatesSync(payload) {
	const requestId = crypto.randomUUID();
	const gatewayRequest = {
		path: '/release/data-templates/sync',
		method: 'POST',
		headers: {
			'Content-Type': 'application/json',
			'x-event-id': requestId,
			'x-locale': locale || 'en',
			'platform-experience': 'sfdx',
			'x-copado-api-url': CF_SF_ENDPOINT
		},
		body: payload
	};

	const safeJsonStr = JSON.stringify(gatewayRequest).replace(/'/g, "'\\''");
	const command = `copado --gateway '${safeJsonStr}'`;

	this.logger(`Generated Event ID: ${requestId}`);
	this.logger('Calling Copado CLI Gateway /data-templates/sync...');
	const output = await this.executeCommand(command);

	this.logger(`Raw gateway output received for JSON parsing: "${output}"`);
	try {
		return JSON.parse(output);
	} catch (error) {
		throw new SyncError(`Unable to parse gateway response as JSON: ${error.message}`);
	}
}

async function handleSyncResponse(syncResponse) {
	const parsedResponse = this.parseSyncResponse(syncResponse);
	this.uploadSyncResult(parsedResponse.entries);
	this.logSyncResponse(parsedResponse);

	if (parsedResponse.status === 'error') {
		throw new SyncError(this.formatGatewayErrorMessage(parsedResponse));
	}

	const attentionEntries = parsedResponse.entries.filter(entry => entry?.needsAttention === true);
	const failedSyncEntries = parsedResponse.entries.filter(entry => entry?.synced === false);

	if (attentionEntries.length) {
		this.logger(
			`WARN: ${attentionEntries.length} of ${parsedResponse.entries.length} sync operation(s) need attention; step will continue`
		);
	}

	if (failedSyncEntries.length) {
		const errorDetails = failedSyncEntries
			.map(entry => {
				const identity = [
					entry.mainTemplateId,
					entry.templateId,
					entry.objectApiName,
					entry.fieldApiName,
					entry.operation
				]
					.filter(Boolean)
					.join('/');
				return `${identity}: ${entry.errorMessage || 'Sync failed'}`;
			})
			.join('; ');
		throw new SyncError(
			`Data template sync completed with ${failedSyncEntries.length} failed sync operation(s): ${errorDetails}`
		);
	}

	if (attentionEntries.length) {
		this.logger(
			`Data template sync completed for ${parsedResponse.entries.length} operation(s) with entries needing attention`
		);
	} else {
		this.logger(`Data template sync succeeded for ${parsedResponse.entries.length} operation(s)`);
	}

	return parsedResponse;
}

function parseSyncResponse(syncResponse) {
	if (Array.isArray(syncResponse)) {
		return {
			status: 'success',
			message: 'Operation successful',
			entries: syncResponse,
			errorData: null
		};
	}

	if (!syncResponse || typeof syncResponse !== 'object') {
		throw new SyncError('Unexpected gateway response format');
	}

	const status = String(syncResponse.status || '').toLowerCase() || 'success';
	const message = syncResponse.message || '';

	if (status === 'error') {
		return {
			status,
			message,
			entries: [],
			errorData: syncResponse.data || null
		};
	}

	if (Array.isArray(syncResponse.data)) {
		return {
			status,
			message,
			entries: syncResponse.data,
			errorData: null
		};
	}

	if (Array.isArray(syncResponse.body)) {
		return {
			status,
			message,
			entries: syncResponse.body,
			errorData: null
		};
	}

	throw new SyncError('Unexpected gateway response format; expected status/message/data payload');
}

function logSyncResponse(parsedResponse) {
	this.logger(`Gateway status: ${parsedResponse.status}`);
	if (parsedResponse.message) {
		this.logger(`Gateway message: ${parsedResponse.message}`);
	}

	if (parsedResponse.status === 'error') {
		const errorRows = [this.toErrorTableRow(parsedResponse)];
		this.logger('Data Templates Sync Error:');
		console.table(errorRows);
		return;
	}

	const tableRows = parsedResponse.entries.map(entry => this.toSyncResultTableRow(entry));
	this.logger('Data Templates Sync Results:');
	if (!tableRows.length) {
		this.logger('No sync result entries returned by the gateway');
		return;
	}
	console.table(tableRows);
}

function toSyncResultTableRow(entry) {
	return {
		'Main Template Id': entry?.mainTemplateId || '',
		'Template Id': entry?.templateId || '',
		'Template Name': entry?.templateName || '',
		Object: entry?.objectApiName || '',
		Field: entry?.fieldApiName || '',
		Type: entry?.fieldType || '',
		Operation: entry?.operation || '',
		Synced: entry?.synced === true ? 'Yes' : 'No',
		'Needs Attention': entry?.needsAttention === true ? 'Yes' : 'No',
		'Error Message': entry?.errorMessage || ''
	};
}

function toErrorTableRow(parsedResponse) {
	const details = parsedResponse.errorData?.details;
	const detailMessage =
		typeof details === 'string'
			? details
			: details?.message || JSON.stringify(details || parsedResponse.errorData || {});

	return {
		Status: parsedResponse.status,
		Message: parsedResponse.message || '',
		Code: parsedResponse.errorData?.code || '',
		Category: details?.category || '',
		Details: detailMessage
	};
}

function formatGatewayErrorMessage(parsedResponse) {
	const details = parsedResponse.errorData?.details;
	const detailMessage =
		typeof details === 'string'
			? details
			: details?.message || JSON.stringify(parsedResponse.errorData || {});
	const code = parsedResponse.errorData?.code ? ` [${parsedResponse.errorData.code}]` : '';
	return `${parsedResponse.message || 'Data template sync failed'}${code}: ${detailMessage}`;
}

function uploadSyncResult(syncResultEntries) {
	try {
		fs.mkdirSync(TEMP_DIRECTORY, { recursive: true });
		const resultFilePath = path.join(TEMP_DIRECTORY, SYNC_RESULT_FILE_NAME);
		fs.writeFileSync(resultFilePath, JSON.stringify(syncResultEntries, null, 2));
		const escapedPath = resultFilePath.replace(/'/g, "'\\''");
		this.executeCommandSync(
			`copado --uploadfile '${escapedPath}' --name '${SYNC_RESULT_FILE_NAME}'`
		);
	} catch (error) {
		this.logger(`WARN: Unable to upload sync result file: ${error.message}`);
	}
}

// UTILITY FUNCTIONS

function readJsonFile(filePath) {
	const content = fs.readFileSync(filePath, 'utf-8');
	try {
		return JSON.parse(content);
	} catch (error) {
		throw new ValidationError(`Content at ${filePath} is not valid JSON: ${error.message}`);
	}
}

function getPath(filePath) {
	return isTest ? `${__dirname}/__tests__/__mockDirectory__${filePath}` : filePath;
}

function executeCommand(command) {
	this.logger(`===> ${command}`);
	return new Promise((resolve, reject) => {
		let output = '';
		let error = '';

		const childProcess = child_process.spawn(command, [], { shell: true });

		childProcess.stdout.on('data', data => {
			const outputStream = data?.toString();
			this.logger(outputStream);
			output += outputStream;
		});

		childProcess.stderr.on('data', data => {
			const errorStream = data?.toString();
			this.logger(errorStream);
			error += errorStream;
		});

		childProcess.on('close', code => {
			if (code !== 0) {
				this.logger(`Code: ${code}`);
				const errorMessage = error || `Error executing the command ${command.trim()}`;
				const truncatedError = JSON.stringify(
					errorMessage
						.split('\n')
						.filter(msg => !msg.includes(COPADO_INFO_PREFIX))
						.join(' ')
				);
				reject(new CommandExecutionError(truncatedError));
				return;
			}
			resolve(output);
		});

		childProcess.on('error', err => {
			const truncatedError = JSON.stringify(
				String(err)
					.split('\n')
					.filter(msg => !msg.includes(COPADO_INFO_PREFIX))
					.join(' ')
			);
			reject(new CommandExecutionError(truncatedError));
		});
	});
}

function executeCommandSync(command) {
	this.logger(`===> ${command}`);
	const response = child_process.spawnSync(command, { shell: true, encoding: 'utf-8' });
	if (response.status !== 0) {
		const errorMessage =
			response.stderr || response.stdout || `Error executing the command ${command.trim()}`;
		throw new CommandExecutionError(String(errorMessage).trim());
	}
	return response.stdout;
}

function logger(text) {
	console.log(text);
}

class CommandExecutionError extends Error {
	constructor(message) {
		super(message);
		this.name = CUSTOM_ERROR.COMMAND_EXECUTION_ERROR;
	}
}

class ValidationError extends Error {
	constructor(message) {
		super(message);
		this.name = CUSTOM_ERROR.VALIDATION_ERROR;
	}
}

class SyncError extends Error {
	constructor(message) {
		super(message);
		this.name = CUSTOM_ERROR.SYNC_ERROR;
	}
}

module.exports.execute = execute;
module.exports.parseContentVersionIds = parseContentVersionIds;
module.exports.downloadAndReadSyncConfigs = downloadAndReadSyncConfigs;
module.exports.downloadContentVersion = downloadContentVersion;
module.exports.readDownloadedSyncConfig = readDownloadedSyncConfig;
module.exports.buildSyncPayload = buildSyncPayload;
module.exports.filterSyncConfigsForEnvironment = filterSyncConfigsForEnvironment;
module.exports.deduplicateSyncConfigs = deduplicateSyncConfigs;
module.exports.getSyncConfigDedupeKey = getSyncConfigDedupeKey;
module.exports.toSyncRequestEntry = toSyncRequestEntry;
module.exports.callDataTemplatesSync = callDataTemplatesSync;
module.exports.handleSyncResponse = handleSyncResponse;
module.exports.parseSyncResponse = parseSyncResponse;
module.exports.logSyncResponse = logSyncResponse;
module.exports.toSyncResultTableRow = toSyncResultTableRow;
module.exports.toErrorTableRow = toErrorTableRow;
module.exports.formatGatewayErrorMessage = formatGatewayErrorMessage;
module.exports.uploadSyncResult = uploadSyncResult;
module.exports.readJsonFile = readJsonFile;
module.exports.getPath = getPath;
module.exports.executeCommand = executeCommand;
module.exports.executeCommandSync = executeCommandSync;
module.exports.logger = logger;

!isTest && this.execute();
